/**
 * Cloudflare Worker entry: the OpenNext-built Next.js app, plus a `scheduled`
 * handler that turns Cron Triggers (wrangler.jsonc) into calls to the
 * existing /api/cron/* routes, the way Vercel Cron did.
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build` (absent before the first build)
import { default as handler } from "./.open-next/worker.js";

const CRON_ROUTES: Record<string, string> = {
  "17 9 * * *": "/api/cron/gmail-watch",
  "*/10 * * * *": "/api/cron/gmail-reconcile",
  "7 14 * * *": "/api/cron/daily",
  "0 23 * * FRI": "/api/cron/digest",
  "0 0 * * SAT": "/api/cron/digest-winter",
};

interface Env {
  CRON_SECRET?: string;
  APP_URL?: string;
}

export default {
  fetch: handler.fetch,

  async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    const path = CRON_ROUTES[controller.cron];
    if (!path) {
      console.error(`No route for cron "${controller.cron}"; update CRON_ROUTES in worker.ts`);
      return;
    }
    const origin = env.APP_URL?.replace(/\/+$/, "") || "https://groupdesk.invalid";
    const req = new Request(new URL(path, origin), {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    const res: Response = await handler.fetch(req, env, ctx);
    const body = await res.text();
    if (!res.ok) throw new Error(`${path} -> ${res.status}: ${body.slice(0, 500)}`);
    console.log(`${path} -> ${res.status}: ${body.slice(0, 500)}`);
  },
} satisfies ExportedHandler<Env>;

// Re-export the Durable Objects OpenNext's worker declares, so the bundle
// matches whatever it expects to be exported.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build` (absent before the first build)
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
